254	func containsHit(hits []TxHit, want TxHit) bool {
255		for _, hit := range hits {
256			if hit == want {
257				return true
258			}
259		}
260		return false
261	}
262	
263	func requireOrdered(t *testing.T, hits []TxHit) {
264		t.Helper()
265		for i := 1; i < len(hits); i++ {
266			prev, cur := hits[i-1], hits[i]
267			if cur.Height < prev.Height || (cur.Height == prev.Height && cur.Position <= prev.Position) {
268				t.Fatalf("hits not ordered at %d: %+v after %+v", i, cur, prev)
269			}
270		}
271	}
272	
273	// classifyTxPage accepts got only when its visible contents are the first-page
274	// view of exactly one chain. The opaque NextCursor is not part of this view;
275	// callers validate it by following it. Record provenance is checked against
276	// the COMPLETE branch hit lists, not just the records on the reference page,
277	// so a stitched page drawn from later heights is still exposed. It does NOT
278	// treat "hit count equals TotalMatches" as sufficient: an ordered, correctly
279	// counted stitched page still carries records from both branches.
280	func classifyTxPage(got, oldRef, newRef TxPage, oldAllHits, newAllHits []TxHit) error {
281		type view struct {
282			Hits          []TxHit
283			TotalMatches  int64
284			MatchedBlocks int64
285			ToHeight      int64
286		}
287		of := func(p TxPage) view {
288			return view{Hits: p.Hits, TotalMatches: p.TotalMatches, MatchedBlocks: p.MatchedBlocks, ToHeight: p.ToHeight}
289		}
290		g, o, n := of(got), of(oldRef), of(newRef)
291		if reflect.DeepEqual(g, o) || reflect.DeepEqual(g, n) {
292			return nil
293		}
294	
295		var report strings.Builder
296		fmt.Fprintln(&report, "QueryTxs page does not match one complete main chain:")
297		tags := map[string]bool{}
298		tag := func(name string, gotV, oldV, newV any) {
299			matchesOld := reflect.DeepEqual(gotV, oldV)
300			matchesNew := reflect.DeepEqual(gotV, newV)
301			label := "neither"
302			switch {
303			case matchesOld && matchesNew:
304				label = "both"
305			case matchesOld:
306				label = "OLD"
307				tags["old"] = true
308			case matchesNew:
309				label = "NEW"
310				tags["new"] = true
311			}
312			fmt.Fprintf(&report, "  %-15s got=%v old=%v new=%v -> %s\n", name, gotV, oldV, newV, label)
313		}
314		tag("ToHeight", g.ToHeight, o.ToHeight, n.ToHeight)
315		tag("TotalMatches", g.TotalMatches, o.TotalMatches, n.TotalMatches)
316		tag("MatchedBlocks", g.MatchedBlocks, o.MatchedBlocks, n.MatchedBlocks)
317	
318		// Record-level provenance: each hit must be explainable by the same chain
319		// at the same page offset. This is what rejects an ordered-looking page
320		// that interleaves two branches.
321		oldByKey := map[TxHit]bool{}
322		newByKey := map[TxHit]bool{}
323		for _, h := range oldAllHits {
324			oldByKey[h] = true
325		}
326		for _, h := range newAllHits {
327			newByKey[h] = true
328		}
329		var inOld, inNew, inNeither int
330		var onlyOld, onlyNew int
331		ordered := true
332		for i, h := range g.Hits {
333			co, cn := oldByKey[h], newByKey[h]
334			if co {
335				inOld++
336			}
337			if cn {
338				inNew++
339			}
340			if co && !cn {
341				onlyOld++
342			}
343			if cn && !co {
344				onlyNew++
345			}
346			if !co && !cn {
347				inNeither++
348			}
349			if i > 0 {
350				prev := g.Hits[i-1]
351				if h.Height < prev.Height || (h.Height == prev.Height && h.Position <= prev.Position) {
352					ordered = false
353				}
354			}
355			if h.Height > g.ToHeight {
356				fmt.Fprintf(&report, "  hit above pinned ToHeight %d: %+v\n", g.ToHeight, h)
357			}
358		}
359		fmt.Fprintf(&report, "  Hits provenance  on-old=%d on-new=%d only-old=%d only-new=%d on-neither=%d (ordered=%v)\n",
360			inOld, inNew, onlyOld, onlyNew, inNeither, ordered)
361		// A record that belongs to exactly one branch tags that branch; shared
362		// ancestor records tag neither.
363		if onlyOld > 0 {
364			tags["old"] = true
365		}
366		if onlyNew > 0 {
367			tags["new"] = true
368		}
369		switch {
370		case tags["old"] && tags["new"]:
371			fmt.Fprintf(&report, "  => MIXED: stats and records come from both the old and the new chain; one page must reflect a single main chain")
372		case inNeither > 0:
373			fmt.Fprintf(&report, "  => CORRUPT: records exist on neither chain")
374		default:
375			fmt.Fprintf(&report, "  => CORRUPT: matches neither the old nor the new chain")
376		}
377		return errors.New(report.String())
378	}
379	
380	// The classifier must accept both complete answers and reject ordered-looking
381	// mixtures and plain corruption.
382	func TestClassifyTxPageRejectsMixedAndCorruptPages(t *testing.T) {
383		oldRef := literalOldFirstPage()
384		newRef := literalNewFirstPage()
385		oldAll := referenceTxHits(queryOldChainBlocks())
386		newAll := referenceTxHits(queryNewChainBlocks())
387		classify := func(page TxPage) error { return classifyTxPage(page, oldRef, newRef, oldAll, newAll) }
388		if err := classify(oldRef); err != nil {
389			t.Fatalf("pure old page rejected: %v", err)
390		}
391		if err := classify(newRef); err != nil {
392			t.Fatalf("pure new page rejected: %v", err)
393		}
394	
395		// Mixture 1: shared first-page records (identical on both chains), but
396		// new-chain counts under the OLD tip height. Hit count still equals the
397		// total on both chains, so a count-equality check would accept it.
398		mixed1 := newRef
399		mixed1.ToHeight = oldRef.ToHeight
400		if int64(len(mixed1.Hits)) != 3 || mixed1.TotalMatches != 8 {
401			t.Fatal("test setup: mixed1 counts are meant to look internally consistent")
402		}
403		if err := classify(mixed1); err == nil {
404			t.Fatal("new-chain counts under the old tip height were accepted")
405		} else if !strings.Contains(err.Error(), "MIXED") {
406			t.Fatalf("mixed1 not reported as MIXED:\n%v", err)
407		}
408	
409		// Mixture 2: old-chain counts and records under the NEW shortened tip
410		// height — claims tip 4 while still counting removed height 5.
411		mixed2 := oldRef
412		mixed2.ToHeight = newRef.ToHeight
413		if err := classify(mixed2); err == nil {
414			t.Fatal("old-chain counts under the new tip height were accepted")
415		} else if !strings.Contains(err.Error(), "MIXED") {
416			t.Fatalf("mixed2 not reported as MIXED:\n%v", err)
417		}
418	
419		// Mixture 3: an ordered-looking page (height 3 positions 0 and 1) that
420		// stitches one old-branch record to one new-branch record, tagged old by
421		// its stale tip height.
422		mixed3 := oldRef
423		mixed3.Hits = []TxHit{
424			{Height: 3, BlockHash: "h3", TxID: "a", Position: 0},
425			{Height: 3, BlockHash: "j3", TxID: "q", Position: 1},
426		}
427		if err := classify(mixed3); err == nil {
428			t.Fatal("stitched hits from both branches were accepted")
429		} else if !strings.Contains(err.Error(), "MIXED") {
430			t.Fatalf("mixed3 not reported as MIXED:\n%v", err)
431		}
432	
433		// Corruption: stats belonging to no chain at all.
434		corrupt := newRef
435		corrupt.MatchedBlocks = 99
436		if err := classify(corrupt); err == nil {
437			t.Fatal("corrupt stats matching neither chain were accepted")
438		}
439	}
