1	package indexroom
2	
3	import (
4		"errors"
5		"fmt"
6		"reflect"
7		"strings"
8		"testing"
9	)
10	
11	// This file is the OrderDesc twin of query_reorg_test.go. The existing
12	// concurrent shortening-reorg regression drives QueryTxs in the default
13	// ascending direction; here a descending, tip-bound, filtered first page is
14	// forced to overlap a reorg that makes the chain shorter, and every page must
15	// still answer from ONE complete main chain: its visible hits (height, block
16	// hash, original position), the whole-range statistics, and the pinned upper
17	// height must all describe the same branch.
18	//
19	// Old chain, tip 4 (heights 1..4 consecutive):
20	//
21	//	h1 parent g  txs [a, b, a]
22	//	o2 parent h1 txs [a, c]
23	//	o3 parent o2 txs [b, a]
24	//	o4 parent o3 txs [a, a, b]
25	//
26	// New legal branch, tip 3: h1 is retained; heights 2..3 are replaced:
27	//
28	//	h1 parent g  txs [a, b, a]
29	//	n2 parent h1 txs [a, a]
30	//	n3 parent n2 txs [c, a, a]
31	//
32	// The query filters "a" only, starts at height 1, leaves To at zero (the
33	// first page pins the tip it sees), page size 3, empty cursor, OrderDesc.
34	//
35	// Old-chain first page (range 1..4, descending positions kept):
36	//
37	//	(4,1,o4,a), (4,0,o4,a), (3,1,o3,a)
38	//
39	// Whole range: 6 occurrences of a across 4 blocks, real upper bound 4, and a
40	// non-empty cursor (three more occurrences remain). The two a's inside o4 are
41	// separate occurrences at their original positions 1 and 0.
42	//
43	// New-chain first page (range 1..3):
44	//
45	//	(3,2,n3,a), (3,1,n3,a), (2,1,n2,a)
46	//
47	// Whole range: still 6 occurrences, but only 3 blocks hold an a, the real
48	// upper bound is 3, and a cursor remains. No hash of the removed height 4 or
49	// the replaced blocks (o2, o3, o4) may appear on this page.
50	
51	func descOldChainBlocks() []Block {
52		return []Block{
53			{Height: 1, Hash: "h1", Parent: "g", Txs: []string{"a", "b", "a"}},
54			{Height: 2, Hash: "o2", Parent: "h1", Txs: []string{"a", "c"}},
55			{Height: 3, Hash: "o3", Parent: "o2", Txs: []string{"b", "a"}},
56			{Height: 4, Hash: "o4", Parent: "o3", Txs: []string{"a", "a", "b"}},
57		}
58	}
59	
60	func descNewBranchBlocks() []Block {
61		return []Block{
62			{Height: 2, Hash: "n2", Parent: "h1", Txs: []string{"a", "a"}},
63			{Height: 3, Hash: "n3", Parent: "n2", Txs: []string{"c", "a", "a"}},
64		}
65	}
66	
67	func descNewChainBlocks() []Block {
68		return []Block{
69			{Height: 1, Hash: "h1", Parent: "g", Txs: []string{"a", "b", "a"}},
70			{Height: 2, Hash: "n2", Parent: "h1", Txs: []string{"a", "a"}},
71			{Height: 3, Hash: "n3", Parent: "n2", Txs: []string{"c", "a", "a"}},
72		}
73	}
74	
75	func buildDescOldChain(t *testing.T) *Index {
76		t.Helper()
77		index := New()
78		for _, b := range descOldChainBlocks() {
79			if err := index.Append(b); err != nil {
80				t.Fatalf("setup append at %d: %v", b.Height, err)
81			}
82		}
83		return index
84	}
85	
86	// descReferenceHits is an independent descending oracle built straight from
87	// an explicit chain, not from the Index under test: decreasing height, and
88	// inside one block decreasing original position, "a" occurrences only.
89	func descReferenceHits(chain []Block) []TxHit {
90		hits := []TxHit{}
91		for i := len(chain) - 1; i >= 0; i-- {
92			block := chain[i]
93			for position := len(block.Txs) - 1; position >= 0; position-- {
94				if block.Txs[position] != "a" {
95					continue
96				}
97				hits = append(hits, TxHit{
98					Height:    block.Height,
99					BlockHash: block.Hash,
100					TxID:      "a",
101					Position:  position,
102				})
103			}
104		}
105		return hits
106	}
107	
108	func descReferenceMatchedBlocks(chain []Block) int64 {
109		var blocks int64
110		for _, block := range chain {
111			for _, tx := range block.Txs {
112				if tx == "a" {
113					blocks++
114					break
115				}
116			}
117		}
118		return blocks
119	}
120	
121	// descReferencePage slices one page at the given offset of the oracle's full
122	// descending occurrence list and attaches the statistics over the WHOLE
123	// filtered range, not just the page. The cursor stays opaque and is checked
124	// separately.
125	func descReferencePage(chain []Block, pageSize int, offset int64) TxPage {
126		full := descReferenceHits(chain)
127		rest := full[offset:]
128		end := pageSize
129		if end > len(rest) {
130			end = len(rest)
131		}
132		return TxPage{
133			Hits:          append([]TxHit{}, rest[:end]...),
134			TotalMatches:  int64(len(full)),
135			MatchedBlocks: descReferenceMatchedBlocks(chain),
136			ToHeight:      chain[len(chain)-1].Height,
137		}
138	}
139	
140	// Literal first pages, as derived by hand in the brief: the guarantee rests on
141	// these exact records, not on an oracle-vs-oracle DeepEqual.
142	func literalDescOldFirstPage() TxPage {
143		return TxPage{
144			Hits: []TxHit{
145				{Height: 4, BlockHash: "o4", TxID: "a", Position: 1},
146				{Height: 4, BlockHash: "o4", TxID: "a", Position: 0},
147				{Height: 3, BlockHash: "o3", TxID: "a", Position: 1},
148			},
149			TotalMatches:  6,
150			MatchedBlocks: 4,
151			ToHeight:      4,
152		}
153	}
154	
155	func literalDescNewFirstPage() TxPage {
156		return TxPage{
157			Hits: []TxHit{
158				{Height: 3, BlockHash: "n3", TxID: "a", Position: 2},
159				{Height: 3, BlockHash: "n3", TxID: "a", Position: 1},
160				{Height: 2, BlockHash: "n2", TxID: "a", Position: 1},
161			},
162			TotalMatches:  6,
163			MatchedBlocks: 3,
164			ToHeight:      3,
165		}
166	}
167	
168	func requireDescOrdered(t *testing.T, hits []TxHit) {
169		t.Helper()
170		for i := 1; i < len(hits); i++ {
171			prev, cur := hits[i-1], hits[i]
172			if cur.Height > prev.Height || (cur.Height == prev.Height && cur.Position >= prev.Position) {
173				t.Fatalf("hits not descending at %d: %+v after %+v", i, cur, prev)
174			}
175		}
176	}
177	
178	// The counting and ordering semantics the regression rests on, asserted on
179	// both chains and cross-checked against the live index before and after the
180	// shortening reorg.
181	func TestReorgDescQueryFixtureSemanticsOnBothChains(t *testing.T) {
182		oldChain := descOldChainBlocks()
183		newChain := descNewChainBlocks()
184	
185		// Setup invariant: every suffix hash that vanishes must be distinct from
186		// every hash the new branch carries, or a torn page could hide itself.
187		newHashes := map[string]bool{}
188		for _, b := range newChain[1:] {
189			newHashes[b.Hash] = true
190		}
191		for _, gone := range []string{"o2", "o3", "o4"} {
192			if newHashes[gone] {
193				t.Fatalf("setup invariant broken: removed hash %q is present on the new branch", gone)
194			}
195		}
196	
197		oldHits := descReferenceHits(oldChain)
198		if want := literalDescOldFirstPage().Hits; !reflect.DeepEqual(oldHits[:3], want) {
199			t.Fatalf("old chain first three=%v, want literal %v", oldHits[:3], want)
200		}
201		if len(oldHits) != 6 || descReferenceMatchedBlocks(oldChain) != 4 {
202			t.Fatalf("old chain: matches=%d blocks=%d, want 6/4", len(oldHits), descReferenceMatchedBlocks(oldChain))
203		}
204		// All six occurrences, including the repeated a's inside one block.
205		wantOldAll := []TxHit{
206			{Height: 4, BlockHash: "o4", TxID: "a", Position: 1},
207			{Height: 4, BlockHash: "o4", TxID: "a", Position: 0},
208			{Height: 3, BlockHash: "o3", TxID: "a", Position: 1},
209			{Height: 2, BlockHash: "o2", TxID: "a", Position: 0},
210			{Height: 1, BlockHash: "h1", TxID: "a", Position: 2},
211			{Height: 1, BlockHash: "h1", TxID: "a", Position: 0},
212		}
213		if !reflect.DeepEqual(oldHits, wantOldAll) {
214			t.Fatalf("old chain full desc walk=%v, want %v", oldHits, wantOldAll)
215		}
216		requireDescOrdered(t, oldHits)
217	
218		newHits := descReferenceHits(newChain)
219		if want := literalDescNewFirstPage().Hits; !reflect.DeepEqual(newHits[:3], want) {
220			t.Fatalf("new chain first three=%v, want literal %v", newHits[:3], want)
221		}
222		if len(newHits) != 6 || descReferenceMatchedBlocks(newChain) != 3 {
223			t.Fatalf("new chain: matches=%d blocks=%d, want 6/3", len(newHits), descReferenceMatchedBlocks(newChain))
224		}
225		requireDescOrdered(t, newHits)
226		for _, h := range newHits {
227			if h.BlockHash == "o2" || h.BlockHash == "o3" || h.BlockHash == "o4" {
228				t.Fatalf("removed/replaced hash %q must not occur on the new chain: %v", h.BlockHash, newHits)
229			}
230			if h.Height > 3 {
231				t.Fatalf("old height %d must not occur on the shortened chain", h.Height)
232			}
233		}
234	
235		// The oracle must match the live index on both complete chain states.
236		index := buildDescOldChain(t)
237		query := TxQuery{TxIDs: []string{"a"}, PageSize: 3, Order: OrderDesc}
238		live, err := index.QueryTxs(query)
239		if err != nil {
240			t.Fatal(err)
241		}
242		if !reflect.DeepEqual(viewOf(live), viewOf(descReferencePage(oldChain, 3, 0))) {
243			t.Fatalf("live old-chain desc page=%+v", live)
244		}
245		dropped, err := index.Reorg(descNewBranchBlocks())
246		if err != nil {
247			t.Fatalf("shortening reorg refused: %v", err)
248		}
249		if want := []int64{2, 3, 4}; !reflect.DeepEqual(dropped, want) {
250			t.Fatalf("dropped=%v, want %v", dropped, want)
251		}
252		if index.Tip != 3 {
253			t.Fatalf("tip after reorg=%d, want 3", index.Tip)
254		}
255		if _, ok := index.Blocks[4]; ok {
256			t.Fatal("height 4 still present after shortening reorg")
257		}
258		if _, ok := index.ByHash["o4"]; ok {
259			t.Fatal("removed hash o4 still indexed")
260		}
261		live, err = index.QueryTxs(query)
262		if err != nil {
263			t.Fatal(err)
264		}
265		if !reflect.DeepEqual(viewOf(live), viewOf(descReferencePage(newChain, 3, 0))) {
266			t.Fatalf("live new-chain desc page=%+v", live)
267		}
268	}
269	
270	// classifyDescTxPage accepts got only when its visible contents are the
271	// filtered first-page view of exactly one chain. The opaque cursor is not part
272	// of the view; callers validate it by following it. Provenance is checked
273	// against the COMPLETE filtered occurrence lists of both branches, so a
274	// stitched page is exposed even when its per-field counts look plausible, and
275	// the descending order is verified independently.
276	func classifyDescTxPage(got, oldRef, newRef TxPage, oldAllHits, newAllHits []TxHit) error {
277		type view struct {
278			Hits          []TxHit
279			TotalMatches  int64
280			MatchedBlocks int64
281			ToHeight      int64
282		}
283		of := func(p TxPage) view {
284			return view{Hits: p.Hits, TotalMatches: p.TotalMatches, MatchedBlocks: p.MatchedBlocks, ToHeight: p.ToHeight}
285		}
286		g, o, n := of(got), of(oldRef), of(newRef)
287		if reflect.DeepEqual(g, o) || reflect.DeepEqual(g, n) {
288			return nil
289		}
290	
291		var report strings.Builder
292		fmt.Fprintln(&report, "desc QueryTxs page does not match one complete main chain:")
293		tags := map[string]bool{}
294		tag := func(name string, gotV, oldV, newV any) {
295			matchesOld := reflect.DeepEqual(gotV, oldV)
296			matchesNew := reflect.DeepEqual(gotV, newV)
297			label := "neither"
298			switch {
299			case matchesOld && matchesNew:
300				label = "both"
301			case matchesOld:
302				label = "OLD"
303				tags["old"] = true
304			case matchesNew:
305				label = "NEW"
306				tags["new"] = true
307			}
308			fmt.Fprintf(&report, "  %-15s got=%v old=%v new=%v -> %s\n", name, gotV, oldV, newV, label)
309		}
310		tag("ToHeight", g.ToHeight, o.ToHeight, n.ToHeight)
311		tag("TotalMatches", g.TotalMatches, o.TotalMatches, n.TotalMatches)
312		tag("MatchedBlocks", g.MatchedBlocks, o.MatchedBlocks, n.MatchedBlocks)
313	
314		// Record-level provenance: every hit must be explainable as the same
315		// (height, hash, position) occurrence on one branch.
316		oldByKey := map[TxHit]bool{}
317		newByKey := map[TxHit]bool{}
318		for _, h := range oldAllHits {
319			oldByKey[h] = true
320		}
321		for _, h := range newAllHits {
322			newByKey[h] = true
323		}
324		// Each branch's hash at a height, so a record that borrows one branch's
325		// position under the other's hash counts as on-neither, not as "shared".
326		hashAt := func(chain []Block) map[int64]string {
327			m := map[int64]string{}
328			for _, b := range chain {
329				m[b.Height] = b.Hash
330			}
331			return m
332		}
333		oldHashAt := hashAt(descOldChainBlocks())
334		newHashAt := hashAt(descNewChainBlocks())
335		var inOld, inNew, inNeither int
336		var onlyOld, onlyNew int
337		ordered := true
338		for i, h := range g.Hits {
339			co, cn := oldByKey[h], newByKey[h]
340			if co {
341				inOld++
342			}
343			if cn {
344				inNew++
345			}
346			if co && !cn {
347				onlyOld++
348			}
349			if cn && !co {
350				onlyNew++
351			}
352			if !co && !cn {
353				inNeither++
354			}
355			if i > 0 {
356				prev := g.Hits[i-1]
357				if h.Height > prev.Height || (h.Height == prev.Height && h.Position >= prev.Position) {
358					ordered = false
359				}
360			}
361			if h.Height > g.ToHeight {
362				fmt.Fprintf(&report, "  hit above pinned ToHeight %d: %+v\n", g.ToHeight, h)
363			}
364			if h.TxID != "a" {
365				fmt.Fprintf(&report, "  non-matching transaction leaked through the filter: %+v\n", h)
366			}
367			if hash, ok := oldHashAt[h.Height]; ok && h.BlockHash != hash {
368				if hash2, ok2 := newHashAt[h.Height]; ok2 && h.BlockHash != hash2 {
369					fmt.Fprintf(&report, "  hit hash %q matches neither branch at height %d\n", h.BlockHash, h.Height)
370				}
371			}
372		}
373		fmt.Fprintf(&report, "  Hits provenance  on-old=%d on-new=%d only-old=%d only-new=%d on-neither=%d (desc-ordered=%v)\n",
374			inOld, inNew, onlyOld, onlyNew, inNeither, ordered)
375		if onlyOld > 0 {
376			tags["old"] = true
377		}
378		if onlyNew > 0 {
379			tags["new"] = true
380		}
381		switch {
382		case tags["old"] && tags["new"]:
383			fmt.Fprintf(&report, "  => MIXED: desc hits and statistics come from both the old and the new chain; one page must reflect a single main chain")
384		case inNeither > 0:
385			fmt.Fprintf(&report, "  => CORRUPT: records exist on neither chain")
386		case !ordered:
387			fmt.Fprintf(&report, "  => CORRUPT: page is not in descending height/position order")
388		default:
389			fmt.Fprintf(&report, "  => CORRUPT: matches neither the old nor the new chain")
390		}
391		return errors.New(report.String())
392	}
393	
394	// The classifier must accept both complete descending answers.
395	func TestClassifyDescTxPageAcceptsBothChains(t *testing.T) {
396		oldChain, newChain := descOldChainBlocks(), descNewChainBlocks()
397		oldRef := descReferencePage(oldChain, 3, 0)
398		newRef := descReferencePage(newChain, 3, 0)
399		oldAll, newAll := descReferenceHits(oldChain), descReferenceHits(newChain)
400		if err := classifyDescTxPage(oldRef, oldRef, newRef, oldAll, newAll); err != nil {
401			t.Fatalf("pure old desc page rejected: %v", err)
402		}
403		if err := classifyDescTxPage(newRef, oldRef, newRef, oldAll, newAll); err != nil {
404			t.Fatalf("pure new desc page rejected: %v", err)
405		}
406	
407		// Old-chain stats (4 blocks, upper bound 4) pinned onto new-chain records
408		// is a torn answer even though both chains have six matches: this is the
409		// exact mistake "do not stitch old hits to new stats" forbids.
410		mixed := newRef
411		mixed.MatchedBlocks = oldRef.MatchedBlocks
412		mixed.ToHeight = oldRef.ToHeight
413		if err := classifyDescTxPage(mixed, oldRef, newRef, oldAll, newAll); err == nil {
414			t.Fatal("new-chain desc hits with old-chain stats were accepted")
415		} else if !strings.Contains(err.Error(), "MIXED") {
416			t.Fatalf("mixed page not reported as MIXED:\n%v", err)
417		}
418	
419		// One removed old-chain record on a page otherwise pinned to the new tip.
420		stale := newRef
421		stale.Hits = append([]TxHit{}, newRef.Hits[:2]...)
422		stale.Hits = append(stale.Hits, TxHit{Height: 4, BlockHash: "o4", TxID: "a", Position: 0})
423		if err := classifyDescTxPage(stale, oldRef, newRef, oldAll, newAll); err == nil {
424			t.Fatal("page carrying removed o4 was accepted")
425		}
426	}
427	
428	// Ordering 1: the descending first page is holding the lock on the complete
429	// OLD chain (tip 4 already pinned) when the shortening reorg starts. It must
430	// finish on the old chain — literal o4/o4/o3 records, statistics 6/4, upper
431	// bound 4, non-empty cursor — and never report ErrInvalidArgument or
432	// ErrQueryChanged for a valid first page. Once the reorg commits, its cursor
433	// is dead with a zeroed ErrQueryChanged.
434	func TestQueryTxsDescFirstPageInFlightObservesCompleteOldChain(t *testing.T) {
435		index := buildDescOldChain(t)
436		h := installQueryReorgHooks(t, true, false, 3)
437		oldChain, newChain := descOldChainBlocks(), descNewChainBlocks()
438	
439		result := make(chan TxPage, 1)
440		errCh := make(chan error, 1)
441		go func() {
442			page, err := index.QueryTxs(TxQuery{TxIDs: []string{"a"}, PageSize: 3, Order: OrderDesc})
443			if err != nil {
444				errCh <- err
445				return
446			}
447			result <- page
448		}()
449	
450		<-h.firstParked // query holds index.mu and has pinned the old tip 4
451		reorgDone := make(chan struct{})
452		go func() {
453			if _, err := index.Reorg(descNewBranchBlocks()); err != nil {
454				errCh <- err
455			}
456			close(reorgDone)
457		}()
458	
459		close(h.releaseFirst) // the desc scan finishes against the complete old chain
460		var got TxPage
461		select {
462		case got = <-result:
463		case err := <-errCh:
464			t.Fatalf("concurrent desc first page failed: %v", err)
465		}
466		want := descReferencePage(oldChain, 3, 0)
467		if err := classifyDescTxPage(got, want, descReferencePage(newChain, 3, 0),
468			descReferenceHits(oldChain), descReferenceHits(newChain)); err != nil {
469			t.Fatalf("in-flight desc first page did not return one complete chain:\n%v", err)
470		}
471		if !reflect.DeepEqual(viewOf(got), viewOf(want)) {
472			t.Fatalf("desc query holding the lock across reorg start must see the old chain:\n%+v", got)
473		}
474		if !reflect.DeepEqual(got.Hits, literalDescOldFirstPage().Hits) {
475			t.Fatalf("old desc first page hits=%v, want literal o4/o4/o3 records", got.Hits)
476		}
477		if got.NextCursor == "" {
478			t.Fatal("old desc first page over 6 matches (page size 3) must carry a cursor")
479		}
480	
481		close(h.releaseReorg) // let the parked reorg commit and return
482		<-reorgDone
483		if index.Tip != 3 {
484			t.Fatalf("tip after reorg=%d, want 3", index.Tip)
485		}
486	
487		// The cursor pins the OLD branch: range to 4, offset 3, descending order,
488		// old fingerprint. On the shortened chain it must fail, not stitch.
489		oldFingerprint := buildDescOldChain(t)
490		payload := decodePayload(t, index, got.NextCursor)
491		if payload.To != 4 || payload.Off != 3 || payload.Order != OrderDesc {
492			t.Fatalf("cursor pins to=%d off=%d order=%d, want 4/3/OrderDesc", payload.To, payload.Off, payload.Order)
493		}
494		if payload.FP != fmt.Sprintf("%x", oldFingerprint.fingerprintLocked(1, 4)) {
495			t.Fatal("cursor fingerprint does not match the complete old chain")
496		}
497		page, err := index.QueryTxs(TxQuery{TxIDs: []string{"a"}, PageSize: 3, Order: OrderDesc, Cursor: got.NextCursor})
498		if !errors.Is(err, ErrQueryChanged) {
499			t.Fatalf("old desc cursor across reorg: err=%v page=%+v, want ErrQueryChanged", err, page)
500		}
501		if errors.Is(err, ErrInvalidArgument) {
502			t.Fatalf("a committed reorg must not be reported as an argument error: %v", err)
503		}
504		if !reflect.DeepEqual(page, TxPage{}) {
505			t.Fatalf("changed desc continuation must return a zeroed page, got %+v", page)
506		}
507	}
508	
509	// Ordering 2: the shortening reorg has fully committed (new chain installed,
510	// Reorg still holding the lock) when the descending first page starts. It
511	// waits, then answers on the complete NEW chain — literal n3/n3/n2 records,
512	// statistics 6/3, upper bound 3 — with no removed or replaced hash anywhere on
513	// the page, and a valid first-page request that never fails with
514	// ErrInvalidArgument or ErrQueryChanged. Its cursor paginates the new chain to
515	// the end.
516	func TestQueryTxsDescFirstPageDuringCommittedReorgObservesCompleteNewChain(t *testing.T) {
517		index := buildDescOldChain(t)
518		h := installQueryReorgHooks(t, true, false, 3)
519		oldChain, newChain := descOldChainBlocks(), descNewChainBlocks()
520	
521		reorgErr := make(chan error, 1)
522		go func() {
523			_, err := index.Reorg(descNewBranchBlocks())
524			reorgErr <- err
525		}()
526		<-h.reorgParked // new branch applied (tip 3), Reorg still holds the lock
527	
528		result := make(chan TxPage, 1)
529		errCh := make(chan error, 1)
530		go func() {
531			page, err := index.QueryTxs(TxQuery{TxIDs: []string{"a"}, PageSize: 3, Order: OrderDesc})
532			if err != nil {
533				errCh <- err
534				return
535			}
536			result <- page
537		}()
538	
539		close(h.releaseReorg) // reorg returns; the first lock the query can get sees the new chain
540		if err := <-reorgErr; err != nil {
541			t.Fatalf("reorg failed: %v", err)
542		}
543		close(h.releaseFirst) // the parked first page can now scan and finish
544	
545		var got TxPage
546		select {
547		case got = <-result:
548		case err := <-errCh:
549			t.Fatalf("desc first page during committed reorg must not fail: %v", err)
550		}
551		want := descReferencePage(newChain, 3, 0)
552		if err := classifyDescTxPage(got, descReferencePage(oldChain, 3, 0), want,
553			descReferenceHits(oldChain), descReferenceHits(newChain)); err != nil {
554			t.Fatalf("desc first page across reorg commit did not return one complete chain:\n%v", err)
555		}
556		if !reflect.DeepEqual(viewOf(got), viewOf(want)) {
557			t.Fatalf("desc query after reorg commit must see the complete new chain:\n%+v", got)
558		}
559		if !reflect.DeepEqual(got.Hits, literalDescNewFirstPage().Hits) {
560			t.Fatalf("new desc first page hits=%v, want literal n3/n3/n2 records", got.Hits)
561		}
562		if got.NextCursor == "" {
563			t.Fatal("new desc first page over 6 matches (page size 3) must carry a cursor")
564		}
565		for _, hit := range got.Hits {
566			if hit.Height > got.ToHeight {
567				t.Fatalf("hit above the pinned bound: %+v", hit)
568			}
569			if hit.BlockHash == "o2" || hit.BlockHash == "o3" || hit.BlockHash == "o4" {
570				t.Fatalf("removed/replaced hash %q leaked into the new-chain page", hit.BlockHash)
571			}
572		}
573	
574		// The cursor pins the NEW branch and drains it exactly: three more a's,
575		// statistics fixed at 6 matches over 3 blocks and upper bound 3.
576		newFingerprint := New()
577		for _, b := range newChain {
578			if err := newFingerprint.Append(b); err != nil {
579				t.Fatal(err)
580			}
581		}
582		payload := decodePayload(t, index, got.NextCursor)
583		if payload.To != 3 || payload.Off != 3 || payload.Order != OrderDesc {
584			t.Fatalf("cursor pins to=%d off=%d order=%d, want 3/3/OrderDesc", payload.To, payload.Off, payload.Order)
585		}
586		if payload.FP != fmt.Sprintf("%x", newFingerprint.fingerprintLocked(1, 3)) {
587			t.Fatal("cursor fingerprint does not match the complete new chain")
588		}
589	
590		second, err := index.QueryTxs(TxQuery{TxIDs: []string{"a"}, PageSize: 3, Order: OrderDesc, Cursor: got.NextCursor})
591		if err != nil {
592			t.Fatalf("new-chain desc continuation failed: %v", err)
593		}
594		wantSecond := descReferencePage(newChain, 3, 3)
595		if !reflect.DeepEqual(viewOf(second), viewOf(wantSecond)) {
596			t.Fatalf("new-chain desc second page=%+v, want %+v", second, wantSecond)
597		}
598		if second.NextCursor != "" {
599			t.Fatalf("six matches over two pages of three: cursor must end, got %q", second.NextCursor)
600		}
601		all := append(append([]TxHit{}, got.Hits...), second.Hits...)
602		if !reflect.DeepEqual(all, descReferenceHits(newChain)) {
603			t.Fatalf("new-chain desc pagination=%v, want %v", all, descReferenceHits(newChain))
604		}
605	}
